let items=[],revs={};
const AISLES=['Produce','Dairy & eggs','Bakery','Meat & fish','Pantry','Frozen','Drinks','Household','Other'];
const list=document.getElementById('list'),nm=document.getElementById('nm'),msg=document.getElementById('msg'),count=document.getElementById('count'),aisleSel=document.getElementById('aisle');
for(const a of AISLES){const o=document.createElement('option');o.value=a;o.textContent=a;aisleSel.appendChild(o);}
aisleSel.value='Other';
function aisleOf(it){return AISLES.includes(it.aisle)?it.aisle:'Other';}
function render(){
 list.textContent='';
 if(!items.length){const p=document.createElement('p');p.textContent='The list is empty. Add your first item above.';list.appendChild(p);}
 let left=0;
 for(const it of items){if(!it.done)left++;}
 for(const a of AISLES){
  const group=items.filter(it=>aisleOf(it)===a);
  if(!group.length)continue;
  const h=document.createElement('h2');h.textContent=a;list.appendChild(h);
  const ul=document.createElement('ul');
  for(const it of group){
   const li=document.createElement('li');li.setAttribute('data-hook','item');if(it.done)li.className='done';
   const lab=document.createElement('label');
   const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!it.done;
   const t=document.createElement('span');t.className='t';t.textContent=it.name;
   lab.appendChild(cb);lab.appendChild(t);
   cb.addEventListener('change',()=>toggle(it.id,cb.checked));
   const sel=document.createElement('select');sel.setAttribute('aria-label','Aisle for '+it.name);
   for(const x of AISLES){const o=document.createElement('option');o.value=x;o.textContent=x;sel.appendChild(o);}
   sel.value=a;
   sel.addEventListener('change',()=>setAisle(it.id,sel.value));
   const rm=document.createElement('button');rm.type='button';rm.setAttribute('data-hook','item-remove');rm.textContent='Remove';rm.setAttribute('aria-label','Remove '+it.name);
   rm.addEventListener('click',()=>remove(it.id));
   li.appendChild(lab);li.appendChild(sel);li.appendChild(rm);ul.appendChild(li);
  }
  list.appendChild(ul);
 }
 count.textContent=items.length?(left+' of '+items.length+' still to get'):'';
}
async function load(){
 const r=await tessera.call('data.read',{});
 items=r.data.items||[];revs=(r.revisions&&r.revisions.items)||{};render();
}
async function toggle(id,done){
 try{await tessera.call('data.patch',{operations:[{op:'replace',collection:'items',id:id,revisionCount:revs[id],fields:{done:done}}]});msg.textContent='';}
 catch(e){msg.textContent='Could not update that item. Please try again.';}
 await load();
}
async function setAisle(id,a){
 try{await tessera.call('data.patch',{operations:[{op:'replace',collection:'items',id:id,revisionCount:revs[id],fields:{aisle:a}}]});msg.textContent='';}
 catch(e){msg.textContent='Could not move that item. Please try again.';}
 await load();
}
async function remove(id){
 try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'items',id:id,revisionCount:revs[id]}]});msg.textContent='';}
 catch(e){msg.textContent='Could not remove that item. Please try again.';}
 await load();
}
async function add(){
 const v=nm.value.trim();
 if(!v){msg.textContent='Type an item name first.';nm.focus();return;}
 try{await tessera.call('data.patch',{operations:[{op:'add',collection:'items',record:{name:v,done:false,aisle:aisleSel.value}}]});nm.value='';msg.textContent='';}
 catch(e){msg.textContent='Could not add that item. Your text is still here; please try again.';}
 await load();nm.focus();
}
document.getElementById('add').addEventListener('click',add);
nm.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add();}});
